import {useNavigation} from '@react-navigation/native';
import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import { NavigationName } from '../../../../constants';
import TextCM from '../../../../components/Text';
import ButtonCM from '../../../../components/Button';
import { View as ViewCM } from 'react-native';
import GroupRadio from '../../../../components/GroupRadio';

type Props = {
  onCancel: () => void;
  onConfirm: () => void;
};

const TwoLayerAuthentication = ({onCancel, onConfirm}: Props) => {
  const {t} = useTranslation();

  const navigation = useNavigation();


  const authenticatorData = [
    {
      id: '1',
      label: t('ST.TwoFactor.useGoogleAuthenticator'),
    },
    {
      id: '2',
      label: t('ST.TwoFactor.useEmail'),
    },
  ];

  const [chooseData, setChooseData] = useState(authenticatorData[0]);

  const onPressConfirm = () => {
    if (chooseData.id === '1') {
      navigation.navigate(NavigationName.AuthenticationByGoogle as never);
    }
    if (chooseData.id === '2') {
      navigation.navigate(NavigationName.AuthenticationByMail as never);
    }
    onConfirm();
  };

  const onPressChoose = (item: any) => {
    setChooseData(item);
  };

  return (
    <ViewCM style={styles.container}>
      <TextCM style={styles.txtTitle}>{t('ST.TwoFactor.validMethod')}</TextCM>
      <ViewCM style={styles.viewBody}>
        <GroupRadio
          data={authenticatorData}
          currentValue={chooseData}
          onPressData={onPressChoose}
        />
      </ViewCM>
      <ViewCM style={styles.viewBtn}>
        <ButtonCM
          type="white"
          label={t('CM.BtnCancel')}
          onPress={onCancel}
          style={styles.btn}
        />
        <ButtonCM
          label={t('CM.BtnContinue')}
          onPress={onPressConfirm}
          style={styles.btn}
        />
      </ViewCM>
    </ViewCM>
  );
};

export default TwoLayerAuthentication;
