import React from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import {Modal, View} from 'react-native';
import {isEmpty} from 'lodash';
import {IconSuccessBig, IconConfirmDelete} from '../../assets/images';
import ButtonCM from '../Button';
import TextCM from '../Text';

type Props = {
  onClose: () => void;
  onConfirm?: () => void;
  isVisible: boolean;
  labelCancel?: string;
  labelConfirm?: string;
  labelClose?: string;
  title: string;
  content?: string;
  renderContent?: () => React.ReactNode;
  type?: 'delete' | 'success' | 'error';
  renderIcon?: () => React.ReactNode;
};

const ModalConfirm = ({
  onClose,
  onConfirm,
  isVisible,
  title,
  content,
  labelCancel,
  labelConfirm,
  renderContent,
  type = 'delete',
  renderIcon,
}: Props) => {
  const {t} = useTranslation();

  const getIcon = () => {
    if (type === 'success') {
      return <IconSuccessBig width={81} height={78} />;
    }
    return <IconConfirmDelete width={81} height={78} />;
  };

  const onPressConfirm = () => {
    onConfirm?.();
  };

  const renderFooter = () => {
    if (type === 'success') {
      return (
        <View style={styles.viewBtn}>
          <ButtonCM
            label={labelCancel || t('CM.BtnClose')}
            onPress={onClose}
            style={styles.btn}
          />
        </View>
      );
    }
    return (
      <View style={styles.viewBtn}>
        <ButtonCM
          label={labelCancel || t('CM.BtnCancel')}
          onPress={onClose}
          style={styles.btn}
        />
        <ButtonCM
          label={labelConfirm || t('CM.BtnConfirm')}
          onPress={onPressConfirm}
          style={styles.btn}
        />
      </View>
    );
  };

  return (
    <Modal visible={isVisible} transparent>
      <View style={styles.ctnContainer}>
        <View style={styles.container}>
          <View style={styles.body}>
            <View style={styles.viewIconDelete}>
              {renderIcon ? renderIcon() : getIcon()}
            </View>
            {!isEmpty(title) && (
              <TextCM style={styles.txtTitle}>{title}</TextCM>
            )}
            {!isEmpty(content) && (
              <TextCM style={styles.txtContent}>{content}</TextCM>
            )}
            {renderContent?.()}
          </View>
          {renderFooter()}
        </View>
      </View>
    </Modal>
  );
};

export default ModalConfirm;
