import {isUndefined} from 'lodash';
import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {IDocument} from '../../../model/interface/envelope.interface';

export const getNameTitle = (type: ItemType, t: any) => {
  switch (type) {
    case ItemType.Draft:
      return t('DC.TxtDocumentDraft');
    case ItemType.Inprogress:
    case ItemType.InprogressDocumentOrganization:
      return t('DC.TxtDocumentInprogress');
    case ItemType.Done:
    case ItemType.DoneDocumentOrganization:
      return t('DC.TxtDocumentDone');
    case ItemType.Cancel:
    case ItemType.CancelDocumentOrganization:
      return t('DC.TxtDocumentCancel');
    case ItemType.Reject:
    case ItemType.RejectDocumentOrganization:
      return t('DC.TxtDocumentReject');
    case ItemType.Expired:
    case ItemType.ExpiredDocumentOrganization:
      return t('DC.TxtDocumentExpired');
    case ItemType.SignFlow:
      return t('DC.TxtDocumentSignFlow');
    case ItemType.Trash:
      return t('DC.TxtDocumentTrash');
    case ItemType.CCDocument:
      return t('DC.TxtDocumentCCDocument');
    case ItemType.Favorite:
      return t('DC.TxtDocumentFavorite');
    default:
      return '';
  }
};

export const getPathApi = (
  type: ItemType,
  currentFocusedOrganization?: number | undefined,
  owner?: string,
  orgIn?: string,
): any => {
  let lastValue = Number(orgIn?.split('/').pop());

  const newOrgIn = !isUndefined(currentFocusedOrganization)
    ? lastValue === currentFocusedOrganization
      ? orgIn
      : `${orgIn}/${currentFocusedOrganization}`
    : orgIn;

  switch (type) {
    case ItemType.Draft:
      return {
        path: 'draft',
        params: {
          sort: 'createdDate,desc',
          search: {
            owner,
            orgIn,
          },
        },
      };
    case ItemType.Inprogress:
      return {
        path: 'processing',
        params: {
          sort: 'createdDate,desc',
          search: {
            owner,
            orgIn,
          },
        },
      };
    case ItemType.Done:
      return {
        path: 'completed',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            owner,
            orgIn,
          },
        },
      };
    case ItemType.Cancel:
      return {
        path: 'voided',
        params: {
          sort: 'createdDate,desc',
          search: {
            owner,
            orgIn,
          },
        },
      };
    case ItemType.Reject:
      return {
        path: 'rejected',
        params: {
          sort: 'createdDate,desc',
          search: {
            owner,
            orgIn,
          },
        },
      };
    case ItemType.Expired:
      return {
        path: 'overdue',
        params: {
          sort: 'createdDate,desc',
          search: {
            owner,
            orgIn,
          },
        },
      };
    case ItemType.SignFlow:
      return {
        path: 'completed',
        params: {
          sort: 'createdDate,desc',
          search: {
            recipientEmail: owner,
          },
        },
      };
    case ItemType.Trash:
      return {
        path: 'deleted',
        params: {
          sort: 'createdDate,desc',
          search: {
            owner,
            orgIn,
          },
        },
      };
    case ItemType.CCDocument:
      return {
        path: 'completed',
        params: {
          sort: 'createdDate,desc',
          search: {
            recipientEmail: owner,
            recipientRole: ['cc'],
          },
        },
      };
    case ItemType.Favorite:
      return {
        path: 'all',
        params: {
          sort: 'createdDate,desc',
          search: {
            favourite: {
              personal: owner,
            },
          },
        },
      };
    case ItemType.InprogressDocumentOrganization:
      return {
        path: 'processing',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            orgIn: newOrgIn,
          },
        },
      };
    case ItemType.DoneDocumentOrganization:
      return {
        path: 'completed',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            orgIn: newOrgIn,
          },
        },
      };
    case ItemType.CancelDocumentOrganization:
      return {
        path: 'voided',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            orgIn: newOrgIn,
          },
        },
      };
    case ItemType.RejectDocumentOrganization:
      return {
        path: 'rejected',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            orgIn: newOrgIn,
          },
        },
      };
    case ItemType.ExpiredDocumentOrganization:
      return {
        path: 'overdue',
        params: {
          sort: 'lastModifiedDate,desc',
          search: {
            orgIn: newOrgIn,
          },
        },
      };
    case ItemType.Authen:
      return {
        path: 'all',
        params: {
          sort: 'createdDate,desc',
          search: {
            envelopeCecaRegistrySearch: {
              owner,
              status: 'rejected',
            },
          },
        },
      };
  }
};

export const dataFavorite = (data: IDocument[], dataFavorite: any[]) => {
  return data.map((document: IDocument) => {
    const favoriteItem = dataFavorite.find(
      (fav: {resourceId: string}) => fav.resourceId === document.id,
    );
    if (favoriteItem) {
      return {...document, favorites: favoriteItem};
    }
    return {...document, favorites: null};
  });
};
