import {View} from 'react-native';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import PicDateView from './components/PicDateView';
import PicStatusView from './components/PicStatusView';
import SortDateView from './components/SortDateView';
import {getTerms, GroupData} from './helper';
import {isEmpty} from 'lodash';
import {StatusNotification} from '../../../../../model/interface/notification.interface';
import {DateUtils} from '../../../../../utils';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';

type DataSearch = {
  search: {
    from?: string | Date | null;
    to?: string | Date | null;
    field?: string;
    terms?: any;
  };
  sort: string | number;
  sort3?: string | number;
};

type Props = {
  toggleShowFilter: () => void;
  isShowFilter: boolean;
  onFilter: (data: any) => void;
  filterData: DataSearch;
};

const ModalFilter = ({
  toggleShowFilter,
  isShowFilter,
  onFilter,
  filterData,
}: Props) => {
  const {t} = useTranslation();

  const [sortDate, setSortDate] = useState<GroupData | null>();
  const [picType, setPicType] = useState<GroupData | undefined>();
  const [fromDate, setFromDate] = useState(null);
  const [toDate, setToDate] = useState(null);

  useEffect(() => {
    if (isEmpty(filterData)) {
      resetData();
    }
  }, [filterData]);

  const resetData = () => {
    setFromDate(null);
    setToDate(null);
    setSortDate(null);
    setPicType(undefined);
  };

  const onChangeFromDate = (date: any) => {
    setFromDate(date);
  };

  const onChangeToDate = (date: any) => {
    setToDate(date);
  };

  const onPressRemoveFilter = () => {
    toggleShowFilter();
    onFilter(null);
  };

  const onPressFilter = () => {
    const dataSearch: DataSearch = {
      search: {
        terms: getTerms(picType?.id as StatusNotification),
      },
      sort: sortDate?.id || 'createdDate,desc',
    };
    if (fromDate) {
      dataSearch.search.from = DateUtils.convertDateToStartDay(fromDate);
      dataSearch.search.field = 'createdDate';
    }
    if (toDate) {
      dataSearch.search.to = DateUtils.convertDateToEndDay(toDate);
      dataSearch.search.field = 'createdDate';
    }

    if (sortDate?.id && !sortDate?.id.toString().includes('createdDate')) {
      dataSearch.sort3 = 'createdDate';
    }
    onFilter(dataSearch);
    toggleShowFilter();
  };

  const Content = () => {
    return (
      <View style={styles.container}>
        <View style={styles.viewDate}>
          <PicStatusView value={picType} onPicType={setPicType} />
          <View style={styles.viewPicDate}>
            <PicDateView
              label={t('NT.modal.TxtFromDate')}
              date={fromDate}
              maxDate={toDate}
              onChangeDate={onChangeFromDate}
            />
            <PicDateView
              label={t('NT.modal.TxtToDate')}
              date={toDate}
              minDate={fromDate}
              onChangeDate={onChangeToDate}
            />
          </View>
          <SortDateView
            data={sortDate as GroupData}
            onChangeSortDate={setSortDate}
          />
        </View>
        <View style={styles.footer}>
          <ButtonCM
            label={t('NT.modal.BtnRemoveFilter')}
            onPress={onPressRemoveFilter}
            style={styles.btnFooter}
          />
          <ButtonCM
            label={t('NT.modal.BtnFilter')}
            onPress={onPressFilter}
            style={styles.btnFooter}
          />
        </View>
      </View>
    );
  };

  return (
    <>
      <BottomSheetCM
        title={t('NT.modal.TxtFilter')}
        renderContent={<Content />}
        onClose={toggleShowFilter}
        isVisible={isShowFilter}
      />
    </>
  );
};

export default ModalFilter;
