import {create} from 'zustand';
import {
  IDocumentTemplate,
  IFileDocumentTemplate,
} from '../../../model/interface/envelope.interface';

interface CreateBatchState {
  dataTemplate: IDocumentTemplate | null;
  currentFileTemplate: IFileDocumentTemplate | null;
  dataExcel: any[];

  updateDataTemplate: (dataTemplate: IDocumentTemplate | null) => void;
  updateCurrentFile: (dataFileTemplate: IFileDocumentTemplate | null) => void;
  setDataExcel: (dataExcel: any[]) => void;
}

const initialCreateBatchState: CreateBatchState = {
  dataTemplate: null,
  currentFileTemplate: null,
  dataExcel: [],

  updateDataTemplate: () => {},
  updateCurrentFile: () => {},
  setDataExcel: () => {},
};

const useCreateBatchStore = create<CreateBatchState>(set => ({
  ...initialCreateBatchState,
  updateDataTemplate: (dataTemplate: IDocumentTemplate | null) =>
    set({dataTemplate: dataTemplate}),
  updateCurrentFile: (dataFileTemplate: IFileDocumentTemplate | null) =>
    set({currentFileTemplate: dataFileTemplate}),
  setDataExcel: (dataExcel: any[]) => set({dataExcel: dataExcel}),
}));

export default useCreateBatchStore;
